import{_ as e,o as t,c as i,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"How we operate Ceph at scale","description":"","frontmatter":{"title":"How we operate Ceph at scale","date":"2022-11-10T00:00:00.000Z","updated":"2022-11-11T00:00:00.000Z","tags":["Ceph","分布式存储","自动化","容器化","云计算"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/How_we_operate_Ceph_at_scale.md","filePath":"posts/2022/How_we_operate_Ceph_at_scale.md","lastUpdated":1780459816000}'),o={name:"posts/2022/How_we_operate_Ceph_at_scale.md"};function r(n,a,s,p,c,h){return t(),i("div",null,[...a[0]||(a[0]=[l('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-digitalocean的ceph存储系统运营实践" tabindex="-1">会议主题：DigitalOcean的Ceph存储系统运营实践 <a class="header-anchor" href="#会议主题-digitalocean的ceph存储系统运营实践" aria-label="Permalink to &quot;会议主题：DigitalOcean的Ceph存储系统运营实践&quot;">​</a></h4><h4 id="主讲人-matt-digitalocean存储系统团队" tabindex="-1">主讲人：Matt（DigitalOcean存储系统团队） <a class="header-anchor" href="#主讲人-matt-digitalocean存储系统团队" aria-label="Permalink to &quot;主讲人：Matt（DigitalOcean存储系统团队）&quot;">​</a></h4><h4 id="会议内容总结" tabindex="-1">会议内容总结： <a class="header-anchor" href="#会议内容总结" aria-label="Permalink to &quot;会议内容总结：&quot;">​</a></h4><ol><li><p><strong>公司简介</strong>： DigitalOcean成立于2012年，是一家提供云服务的公司，以简单性为核心理念。公司提供的产品包括SSD支持的虚拟机（Droplet）、可拆卸的Droplet存储（Volumes）和S3兼容的对象存储（Spaces）等。截至2021年，DigitalOcean在全球拥有八个数据中心。</p></li><li><p><strong>团队介绍</strong>： DigitalOcean的存储系统团队由六名工程师组成，致力于实现团队规模与部署规模解耦，并通过自动化减少对SSH的需求。</p></li><li><p><strong>Ceph在DigitalOcean的应用</strong>： Ceph在DigitalOcean用于块存储和对象存储，支持Volumes和Spaces产品。DigitalOcean运营着46个Ceph集群，其中38个为生产集群，总存储容量超过140PB。</p></li><li><p><strong>自动化与运营</strong>： DigitalOcean使用Chef、Ansible和AWX等工具进行配置管理和集群部署。自动化流程覆盖硬件采购、集群部署和维护的全过程。</p></li><li><p><strong>挑战与解决方案</strong>： DigitalOcean通过自动化和优化配置来应对大规模集群的运营挑战。针对性能问题，如PG peering延迟和RGW索引层性能，团队通过调整参数和优化流程来改善性能。</p></li><li><p><strong>未来展望与招聘</strong>： 团队将继续优化自动化流程，探索新的技术解决方案，如Rook，并招聘新的工程师。</p></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>继续推进自动化和优化Ceph集群的运营流程。</li><li>探索和评估新的技术解决方案，如Rook，以提高效率和性能。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>持续监控和优化Ceph集群的性能。</li><li>加强团队建设，吸引和培养新的技术人才。</li><li>定期回顾和更新自动化流程，确保其适应不断变化的技术和业务需求。</li></ul><h4 id="会议结束语" tabindex="-1">会议结束语： <a class="header-anchor" href="#会议结束语" aria-label="Permalink to &quot;会议结束语：&quot;">​</a></h4><ul><li>感谢Matt的精彩分享和团队的辛勤工作。</li><li>期待DigitalOcean在存储领域的进一步发展和创新。</li></ul>',11)])])}const g=e(o,[["render",r]]);export{_ as __pageData,g as default};
